mapper.select:
SELECT evaluation_id,model_request_id,attempt_ordinal,outcome,verdict,criteria_json,summary
FROM ja_plan_evaluation_attempt
WHERE plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
AND run_id=#{runId} AND input_digest=#{inputDigest}
ORDER BY attempt_ordinal DESC LIMIT 1

mapper.update:
UPDATE ja_plan_execution
SET used_model_rounds=used_model_rounds+1,updated_at_ms=#{startedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE run_id=#{runId} AND plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
AND status IN ('RUNNING','VERIFYING')
AND is_pause_requested=0
AND EXISTS (
SELECT 1 FROM ja_plan p
WHERE p.plan_id=ja_plan_execution.plan_id
AND p.plan_id=#{planId}
AND p.owner_thread_id=#{ownerThreadId}
AND p.status='VERIFYING'
AND p.active_run_id=ja_plan_execution.run_id
AND p.active_plan_revision_id=ja_plan_execution.plan_revision_id
)

UPDATE ja_plan_execution
SET used_active_millis=used_active_millis + (
SELECT CAST(MAX(0,#{completedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT} - started_at_ms) AS INTEGER)
FROM ja_plan_evaluation_attempt
WHERE evaluation_id=#{evaluationId} AND model_request_id=#{modelRequestId} AND plan_id=#{planId}
AND plan_revision_id=#{planRevisionId} AND run_id=#{runId}
AND outcome='RUNNING'
),
updated_at_ms=#{completedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE run_id=#{runId} AND plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
AND status IN ('RUNNING','VERIFYING','PAUSED','STOPPED')
AND EXISTS (
SELECT 1 FROM ja_plan_evaluation_attempt
WHERE evaluation_id=#{evaluationId} AND model_request_id=#{modelRequestId} AND plan_id=#{planId}
AND plan_revision_id=#{planRevisionId} AND run_id=#{runId}
AND outcome='RUNNING'
)

UPDATE ja_plan_evaluation_attempt SET outcome=#{outcome},certainty=#{certainty},
input_tokens=#{inputTokens},output_tokens=#{outputTokens},total_tokens=#{totalTokens},
verdict=#{verdict},criteria_json=#{criteriaJson},summary=#{summary},
completed_at_ms=#{completedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE evaluation_id=#{evaluationId} AND model_request_id=#{modelRequestId}
AND plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
AND run_id=#{runId} AND outcome='RUNNING'
